            res += tree[idx];
            idx -= idx & -idx;
        }
        return res;
    }

    // 查询区间和 [l..r]
    int rangeSum(int l, int r) {
        return sum(r) - sum(l - 1);
    }
};

// 计算单组测试数据答案
long long solveCase(int n, const vector<int>& a) {
    // pos[x] 保存能量值 x 的所有出现位置（下标从1开始）
    vector<vector<int>> pos(n + 1);
    for (int i = 1; i <= n; i++) {
        pos[a[i]].push_back(i);
    }

    Fenwick bit(n);
    long long ans = 0;

    // 按能量值从小到大处理
    for (int v = 1; v <= n; v++) {
        vector<int>& arr = pos[v];

        // 先统计当前值 v 的所有同频紧邻对的低值干扰数
        for (int i = 0; i + 1 < (int)arr.size(); i++) {
            int l = arr[i];
            int r = arr[i + 1];
            ans += bit.rangeSum(l, r);
        }

        // 再将当前值 v 的所有位置加入树状数组
        for (int p : arr) {
            bit.add(p, 1);
        }
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<int> a(n + 1);

        for (int i = 1; i <= n; i++) {
            cin >> a[i];
        }

        cout << solveCase(n, a) << '\n';
    }

    return 0;
}
